contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint v) public payable {
        // Case 1: empty recipient array (violates _tos.length > 0)
        address[] memory emptyTos = new address[](0);
        uint[] memory emptyVals = new uint[](0);
        bool revertedEmpty;
        bool ok1;
        try c.transfer(emptyTos, emptyVals) { ok1 = true; revertedEmpty = false; } catch { ok1 = false; revertedEmpty = true; }

        // Case 2: non-empty arrays, wrong msg.sender
        address[] memory tos = new address[](1);
        uint[] memory vals = new uint[](1);
        tos[0] = to;
        vals[0] = v;
        bool revertedNonEmpty;
        bool ok2;
        try c.transfer(tos, vals) { ok2 = true; revertedNonEmpty = false; } catch { ok2 = false; revertedNonEmpty = true; }

        assert(revertedEmpty && !ok1 && revertedNonEmpty && !ok2);
    }

    receive() external payable {}
}

